const std = @import("std");

const Permissions = packed struct {
    read: bool = false,
    write: bool = false,
    execute: bool = false,
    admin: bool = false,
};

pub fn main() !void {
    var perms = Permissions{ .read = true, .write = true };

    std.debug.print("Initial: {{read: {}, write: {}, exec: {}, admin: {}}}\n", 
        .{perms.read, perms.write, perms.execute, perms.admin});

    perms.execute = true;
    perms.admin = true;
    perms.write = false;

    std.debug.print("Final: {{read: {}, write: {}, exec: {}, admin: {}}}\n", 
        .{perms.read, perms.write, perms.execute, perms.admin});
}

